const raw = $input.first()?.json?.body || $input.first()?.json || {};
const allowedAdmin = $env.TELEGRAM_ADMIN_CHAT_ID || '123456789';

// Handle Callback Query (Button Clicks)
if (raw.callback_query) {
  const cq = raw.callback_query;
  const fromId = String(cq.from?.id);
  const data = cq.data || '';

  return [{
    json: {
      type: 'callback',
      is_authorized: fromId === String(allowedAdmin),
      chat_id: cq.message?.chat?.id || allowedAdmin,
      from_id: fromId,
      callback_query_id: cq.id,
      data: data,
      user_name: cq.from?.username || cq.from?.first_name || 'Admin'
    }
  }];
}

// Handle Direct Messages / Slash Commands
if (raw.message) {
  const msg = raw.message;
  const fromId = String(msg.from?.id);
  const text = (msg.text || '').trim();

  return [{
    json: {
      type: 'message',
      is_authorized: fromId === String(allowedAdmin),
      chat_id: msg.chat?.id || allowedAdmin,
      from_id: fromId,
      text: text,
      user_name: msg.from?.username || msg.from?.first_name || 'Admin'
    }
  }];
}

return [];

const incoming = $('Auth & Dispatcher').first().json;
const rows = $input.all().map(i => i.json);

function progressBar(usedPct) {
  const totalBars = 10;
  const filledBars = Math.min(totalBars, Math.max(0, Math.round((Number(usedPct) || 0) / 10)));
  const emptyBars = totalBars - filledBars;
  return '▓'.repeat(filledBars) + '░'.repeat(emptyBars);
}

let msg = '🎛️ <b>لوحة التحكم اللحظية - راوتر المنزل</b>\n';
msg += '⏱️ التوقيت: <code>' + new Date().toLocaleString('en-GB', { timeZone: 'Africa/Cairo' }) + '</code>\n';
msg += '━━━━━━━━━━━━━━━━━━━━━\n\n';

for (const q of rows) {
  const opBadge = q.operational_state === 'NORMAL' ? '🟢 متصل وطبيعي' : (q.operational_state === 'ISOLATED' ? '🔴 معزول (ISOLATED)' : '🟡 مقيد (THROTTLED)');
  msg += '🌐 <b>' + q.interface_name.toUpperCase() + ' (' + q.provider_name + '):</b>\n';
  msg += '  • الحالة: <b>' + opBadge + '</b>\n';
  msg += '  • الرصيد: [' + progressBar(q.used_percentage) + '] <b>' + q.used_percentage + '%</b>\n';
  msg += '  • المستهلك: <b>' + q.used_gb + ' GB</b> | المتبقي: <b>' + q.remaining_gb + ' GB</b> من ' + q.quota_gb + ' GB\n';
  msg += '  • التجديد: بعد <b>' + q.days_left + ' يوم</b> (' + q.renewal_date + ')\n';
  if (q.daily_burn_rate_gb && Number(q.daily_burn_rate_gb) > 0) {
    msg += '  • معدل الحرق: <b>' + q.daily_burn_rate_gb + ' GB/يوم</b>\n';
    if (q.will_exhaust_before_renewal) {
      msg += '  • ⚠️ <b>نفاد متوقع: ' + q.projected_exhaustion_date + '</b> (قبل التجديد!)\n';
    } else {
      msg += '  • 🎯 نفاد متوقع: ' + q.projected_exhaustion_date + ' (آمن)\n';
    }
  }
  msg += '\n';
}

msg += '━━━━━━━━━━━━━━━━━━━━━\n';
msg += '👇 <i>اختر إجراءً من القائمة أدناه:</i>';

// Build Interactive Inline Keyboard
const keyboard = {
  inline_keyboard: [
    [
      { text: '🔄 تحديث الحالة الآن', callback_data: 'cmd_refresh' },
      { text: '📊 ملخص اليوم', callback_data: 'cmd_today_summary' }
    ],
    [
      { text: '🔴 عزل خط WE (WAN2)', callback_data: 'cmd_isolate_wan2' },
      { text: '🟢 استعادة خط WE (WAN2)', callback_data: 'cmd_restore_wan2' }
    ],
    [
      { text: '🔴 عزل فودافون (WAN1)', callback_data: 'cmd_isolate_wan1' },
      { text: '🟢 استعادة فودافون (WAN1)', callback_data: 'cmd_restore_wan1' }
    ]
  ]
};

return [{
  json: {
    chat_id: incoming.chat_id,
    message: msg,
    reply_markup: keyboard,
    action: incoming.data || incoming.text
  }
}];

const cmd = $('Auth & Dispatcher').first().json.data;
const adminName = $('Auth & Dispatcher').first().json.user_name || 'Admin';

let iface = 'wan2';
let action = 'ISOLATE';

if (cmd === 'cmd_isolate_wan2') {
  iface = 'wan2';
  action = 'ISOLATE';
} else if (cmd === 'cmd_restore_wan2') {
  iface = 'wan2';
  action = 'RESTORE';
} else if (cmd === 'cmd_isolate_wan1') {
  iface = 'wan1';
  action = 'ISOLATE';
} else if (cmd === 'cmd_restore_wan1') {
  iface = 'wan1';
  action = 'RESTORE';
}

// Generate deterministic idempotency key with 60-second window
const timeWindow = Math.floor(Date.now() / 60000);
const idempotencyKey = `tg-${action.toLowerCase()}-${iface}-${timeWindow}`;

return [{
  json: {
    idempotency_key: idempotencyKey,
    router_id: 'home-router-01',
    interface_name: iface,
    action_type: action,
    requested_by: `telegram:@${adminName}`,
    reason: `Manual Telegram command: ${cmd}`,
    chat_id: $('Auth & Dispatcher').first().json.chat_id
  }
}];

