    return `✅ <b>تم تنفيذ الأمر بنجاح!</b>\n\n` +
           `🌐 المنفذ: <code>${$('Prepare Control Action').first().json.interface_name.toUpperCase()}</code>\n` +
           `⚙️ الإجراء: <b>${$('Prepare Control Action').first().json.action_type}</b>\n` +
           `📊 الحالة الجديدة: <b>${r.current_state}</b> (كانت: ${r.previous_state})\n` +
           `🔑 مفتاح التتبع: <code>${r.idempotency_key}</code>`;
  } else {
    return `ℹ️ <b>تنبيه: لم يتغير المسار</b>\n\n` +
           `🌐 المنفذ: <code>${$('Prepare Control Action').first().json.interface_name.toUpperCase()}</code>\n` +
           `الحالة الحالية بالفعل: <b>${r.current_state || 'بدون تغيير'}</b>\n` +
           `السبب: ${r.message}`;
  }
}}
